require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../../includes/planeaciones_service.php';validarPermiso('actualizar_planeaciones');
try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('Usa el formulario de edición.');cufaValidarToken();$id=cufaId($_POST,['id']);$tema=cufaId($_POST,['tema_id']);$p=cufaPlan($pdo,'planeaciones',$id);$pdo->beginTransaction();cufaEditarPlan($pdo,'planeaciones',$id,(int)$p['asignacion_id']);$s=$pdo->prepare('SELECT id FROM temas_materia WHERE id=? AND asignacion_id=?');$s->execute([$tema,$p['asignacion_id']]);if(!$s->fetchColumn())throw new RuntimeException('Tema ajeno a la asignación.');$pdo->prepare("UPDATE planeaciones SET tema_id=?,objetivo=?,actividad=?,descripcion=?,estado='pendiente' WHERE id=?")->execute([$tema,trim($_POST['objetivo']??''),trim($_POST['actividad']??''),trim($_POST['descripcion']??''),$id]);cufaRegistroRevision($pdo,'planeaciones',$id,'pendiente','Corrección guardada.',(int)$_SESSION['user_id']);$pdo->commit();header('Location: '.cufaPanel('detalle_planeacion',['origen'=>'planeaciones','id'=>$id]));exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);cufaError($e);}
